<script>
(function(){const end={{ $deadline->timestamp }}*1000;const timer=document.getElementById('timer');const form=document.getElementById('quiz-form');let sent=false;function tick(){if(sent)return;const left=Math.max(0,Math.floor((end-Date.now())/1000));const m=String(Math.floor(left/60)).padStart(2,'0');const s=String(left%60).padStart(2,'0');timer.textContent=m+':'+s;if(left<=0){sent=true;timer.textContent='Time is up';form.submit();}}tick();setInterval(tick,1000);form.addEventListener('submit',function(){sent=true;});})();
</script>
